pub fn _sys_getenv(key: []const u8) ?[]const u8 {
    if (comptime builtin.os.tag == .windows) {
        const environ: std.process.Environ = .{ .block = .global };
        return environ.getAlloc(_allocator, key) catch null;
    } else {
        return std.posix.getenv(key);
    }
}
